script:
frappe.ui.form.on("Sales Order", {
    refresh(frm) {
        calculate_totals(frm);
    }
});

frappe.ui.form.on("Sales Order Item", {
    item(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!row.item) {
            return;
        }

        frappe.db.get_value("Item", row.item, "rate")
            .then(r => {
                if (r.message && r.message.rate) {
                    frappe.model.set_value(cdt, cdn, "rate", r.message.rate);
                    calculate_row_amount(frm, cdt, cdn);
                }
            });
    },

    quantity(frm, cdt, cdn) {
        calculate_row_amount(frm, cdt, cdn);
    },

    rate(frm, cdt, cdn) {
        calculate_row_amount(frm, cdt, cdn);
    }
});

function calculate_row_amount(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    let quantity = flt(row.quantity);
    let rate = flt(row.rate);

    let amount = quantity * rate;

    frappe.model.set_value(cdt, cdn, "amount", amount);

    calculate_totals(frm);
}

function calculate_totals(frm) {
    let total_quantity = 0;
    let grand_total = 0;

    (frm.doc.items || []).forEach(row => {
        total_quantity += flt(row.quantity);
        grand_total += flt(row.amount);
    });

    frm.set_value("total_quantity", total_quantity);
    frm.set_value("grand_total", grand_total);
}

// ============================================================
// DELIVERY NOTE - COMPLETE CLIENT SCRIPT
// ============================================================


// ------------------------------------------------------------
// 1. FILTER SALES ORDERS BASED ON CUSTOMER
// ------------------------------------------------------------

frappe.ui.form.on("Delivery Note", {

    setup(frm) {

        frm.set_query("sales_order", function () {

            if (!frm.doc.customer) {
                return {};
            }

            return {
                filters: {
                    customer: frm.doc.customer,
                    docstatus: 1
                }
            };
        });
    },


    // --------------------------------------------------------
    // 2. WHEN CUSTOMER IS SELECTED
    // --------------------------------------------------------

    customer(frm) {

        // Clear previous data
        frm.set_value("sales_order", "");
        frm.set_value("customer_name", "");
        frm.set_value("order_date", "");

        frm.clear_table("items");

        frm.set_value("total_quantity", 0);
        frm.set_value("grand_total", 0);

        frm.refresh_field("items");


        // Fetch Customer Name
        if (frm.doc.customer) {

            frappe.db.get_value(
                "Customer",
                frm.doc.customer,
                "customer_name"
            ).then(r => {

                if (r.message) {

                    frm.set_value(
                        "customer_name",
                        r.message.customer_name
                    );
                }
            });
        }
    },


    // --------------------------------------------------------
    // 3. WHEN SALES ORDER IS SELECTED
    // --------------------------------------------------------

    sales_order(frm) {

        if (!frm.doc.sales_order) {
            return;
        }


        // Get complete Sales Order
        frappe.call({

            method: "frappe.client.get",

            args: {
                doctype: "Sales Order",
                name: frm.doc.sales_order
            },


            callback: function (r) {

                if (!r.message) {
                    return;
                }


                let so = r.message;


                // ------------------------------------------------
                // FETCH CUSTOMER
                // ------------------------------------------------

                frm.set_value(
                    "customer",
                    so.customer
                );


                // FETCH CUSTOMER NAME

                frm.set_value(
                    "customer_name",
                    so.customer_name || ""
                );


                // ------------------------------------------------
                // FETCH ORDER DATE
                // ------------------------------------------------

                frm.set_value(
                    "order_date",
                    so.order_date
                );


                // ------------------------------------------------
                // CLEAR OLD ITEMS
                // ------------------------------------------------

                frm.clear_table("items");


                // ------------------------------------------------
                // COPY ITEMS FROM SALES ORDER
                // ------------------------------------------------

                (so.items || []).forEach(function (item) {

                    let row = frm.add_child("items");

                    row.item = item.item;

                    row.item_name =
                        item.item_name || "";

                    row.quantity =
                        item.quantity || 0;

                    row.rate =
                        item.rate || 0;

                    row.amount =
                        item.amount || 0;
                });


                // ------------------------------------------------
                // FETCH TOTAL QUANTITY
                // ------------------------------------------------

                frm.set_value(
                    "total_quantity",
                    so.total_quantity || 0
                );


                // ------------------------------------------------
                // FETCH GRAND TOTAL
                // ------------------------------------------------

                frm.set_value(
                    "grand_total",
                    so.grand_total || 0
                );


                // Refresh child table
                frm.refresh_field("items");

            }
        });
    }
});


// ============================================================
// DELIVERY NOTE ITEM
// FETCH ITEM NAME WHEN ITEM IS SELECTED MANUALLY
// ============================================================

frappe.ui.form.on("Delivery Note Item", {

    item(frm, cdt, cdn) {

        let row = locals[cdt][cdn];


        // If item is removed
        if (!row.item) {

            frappe.model.set_value(
                cdt,
                cdn,
                "item_name",
                ""
            );

            return;
        }


        // Fetch Item Name

        frappe.db.get_value(
            "Item",
            row.item,
            [
                "item_name",
                "stock_quantity"
            ]
        ).then(r => {

            if (r.message) {

                frappe.model.set_value(
                    cdt,
                    cdn,
                    "item_name",
                    r.message.item_name
                );

            }
        });
    }
});

// ============================================================
// SALES INVOICE - COMPLETE CLIENT SCRIPT
// ============================================================

frappe.ui.form.on("Sales Invoice", {

    setup(frm) {

        // ----------------------------------------------------
        // SALES ORDER SHOULD NOT BE MANUALLY EDITED
        // ----------------------------------------------------

        frm.set_df_property(
            "sales_order",
            "read_only",
            1
        );


        // ----------------------------------------------------
        // SHOW ONLY DELIVERY NOTES OF SELECTED CUSTOMER
        // ----------------------------------------------------

        frm.set_query(
            "delivery_note",
            function () {

                if (!frm.doc.customer) {
                    return {};
                }

                return {
                    filters: {
                        customer: frm.doc.customer,
                        docstatus: 1
                    }
                };
            }
        );
    },


    // --------------------------------------------------------
    // WHEN CUSTOMER IS SELECTED
    // --------------------------------------------------------

    customer(frm) {

        // Clear previous data
        frm.set_value(
            "customer_name",
            ""
        );

        frm.set_value(
            "delivery_note",
            ""
        );

        frm.set_value(
            "sales_order",
            ""
        );

        frm.clear_table("items");

        frm.set_value(
            "total_quantity",
            0
        );

        frm.set_value(
            "grand_total",
            0
        );

        frm.set_value(
            "due_date",
            ""
        );

        frm.refresh_field("items");


        // Fetch Customer Name
        if (frm.doc.customer) {

            frappe.db.get_value(
                "Customer",
                frm.doc.customer,
                "customer_name"
            ).then(r => {

                if (r.message) {

                    frm.set_value(
                        "customer_name",
                        r.message.customer_name
                    );

                }

            });

        }

    },


    // --------------------------------------------------------
    // WHEN DELIVERY NOTE IS SELECTED
    // --------------------------------------------------------

    delivery_note(frm) {

        if (!frm.doc.delivery_note) {
            return;
        }


        // Get complete Delivery Note
        frappe.call({

            method: "frappe.client.get",

            args: {
                doctype: "Delivery Note",
                name: frm.doc.delivery_note
            },


            callback: function (r) {

                if (!r.message) {
                    return;
                }


                let dn = r.message;


                // ------------------------------------------------
                // FETCH CUSTOMER
                // ------------------------------------------------

                frm.set_value(
                    "customer",
                    dn.customer
                );


                // ------------------------------------------------
                // FETCH SALES ORDER
                // ------------------------------------------------

                frm.set_value(
                    "sales_order",
                    dn.sales_order
                );


                // ------------------------------------------------
                // CLEAR EXISTING ITEMS
                // ------------------------------------------------

                frm.clear_table("items");


                // ------------------------------------------------
                // COPY ITEMS FROM DELIVERY NOTE
                // ------------------------------------------------

                (dn.items || []).forEach(function (item) {

                    let row = frm.add_child("items");

                    row.item = item.item;

                    row.item_name =
                        item.item_name || "";

                    row.quantity =
                        item.quantity || 0;

                    row.rate =
                        item.rate || 0;

                    row.amount =
                        item.amount || 0;

                });


                // ------------------------------------------------
                // FETCH TOTAL QUANTITY
                // ------------------------------------------------

                frm.set_value(
                    "total_quantity",
                    dn.total_quantity || 0
                );


                // ------------------------------------------------
                // FETCH GRAND TOTAL
                // ------------------------------------------------

                frm.set_value(
                    "grand_total",
                    dn.grand_total || 0
                );


                // Refresh child table
                frm.refresh_field("items");

            }

        });

    },


    // --------------------------------------------------------
    // WHEN INVOICE DATE CHANGES
    // CALCULATE DUE DATE
    // --------------------------------------------------------

    invoice_date(frm) {

        calculate_due_date(frm);

    }

});


// ============================================================
// CALCULATE DUE DATE FROM CUSTOMER PAYMENT TERMS
// ============================================================

function calculate_due_date(frm) {

    if (
        !frm.doc.customer ||
        !frm.doc.invoice_date
    ) {
        return;
    }


    frappe.db.get_value(

        "Customer",
        frm.doc.customer,

        "payment_terms"

    ).then(r => {

        if (!r.message) {
            return;
        }


        let payment_terms =
            r.message.payment_terms;


        let days = 0;


        if (payment_terms === "Immediate") {

            days = 0;

        }

        else if (payment_terms === "15 days") {

            days = 15;

        }

        else if (payment_terms === "30 days") {

            days = 30;

        }

        else if (payment_terms === "45 days") {

            days = 45;

        }

        else if (payment_terms === "60 days") {

            days = 60;

        }


        let due_date =
            frappe.datetime.add_days(
                frm.doc.invoice_date,
                days
            );


        frm.set_value(
            "due_date",
            due_date
        );

    });

}


