frappe.ui.form.on("Sales Order", {
    customer(frm) {

        if (!frm.doc.customer) {
            frm.set_value("customer_name", "");
            return;
        }

        frappe.db.get_value(
            "Customer",
            frm.doc.customer,
            "customer_name"
        ).then(r => {

            if (r.message) {
                frm.set_value(
                    "customer_name",
                    r.message.customer_name
                );
            }

        });
    }
});

frappe.ui.form.on("Sales Order Item", {
    item(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        // Clear values if no item is selected
        if (!row.item) {
            frappe.model.set_value(cdt, cdn, "item_name", "");
            frappe.model.set_value(cdt, cdn, "available_quantity", 0);
            return;
        }

        // Fetch Item Name and Stock Quantity
        frappe.db.get_value(
            "Item",
            row.item,
            ["item_name", "stock_quantity"]
        ).then(r => {

            if (r.message) {

                frappe.model.set_value(
                    cdt,
                    cdn,
                    "item_name",
                    r.message.item_name
                );

                frappe.model.set_value(
                    cdt,
                    cdn,
                    "available_quantity",
                    r.message.stock_quantity
                );

            }

        });
    }
});

frappe.ui.form.on('Sales Order Item', {
    quantity(frm, cdt, cdn) {
        calculate_pending_qty(cdt, cdn);
    },

    delivered_quantity(frm, cdt, cdn) {
        calculate_pending_qty(cdt, cdn);
    }
});

function calculate_pending_qty(cdt, cdn) {
    let row = frappe.get_doc(cdt, cdn);

    let quantity = row.quantity || 0;
    let delivered_quantity = row.delivered_quantity || 0;

    frappe.model.set_value(
        cdt,
        cdn,
        'pending_quantity',
        Math.max(quantity - delivered_quantity, 0)
    );
}

frappe.ui.form.on("Payment Entry", {

    refresh(frm) {

        // Show only submitted invoices
        // belonging to the selected customer
        frm.set_query(
            "reference_sale_invoice",
            function () {

                return {
                    filters: {
                        customer: frm.doc.customer,
                        docstatus: 1
                    }
                };

            }
        );

    },


    customer(frm) {

        // Clear dependent fields
        frm.set_value("customer_name", "");
        frm.set_value("reference_sale_invoice", "");
        frm.set_value("invoice_total", 0);
        frm.set_value("remaining_amount", 0);
        frm.set_value("paid_amount", 0);

        if (!frm.doc.customer) {
            return;
        }

        // Fetch customer name
        frappe.db.get_value(
            "Customer",
            frm.doc.customer,
            "customer_name"
        ).then(r => {

            if (r.message) {

                frm.set_value(
                    "customer_name",
                    r.message.customer_name
                );

            }

        });

    },


    reference_sale_invoice(frm) {

        // Reset values
        frm.set_value("invoice_total", 0);
        frm.set_value("remaining_amount", 0);
        frm.set_value("paid_amount", 0);

        if (!frm.doc.reference_sale_invoice) {
            return;
        }

        // Get Sales Invoice total and customer
        frappe.db.get_value(
            "Sales Invoice",
            frm.doc.reference_sale_invoice,
            [
                "grand_total",
                "customer"
            ]
        ).then(r => {

            if (!r.message) {
                return;
            }

            // Safety check
            if (
                frm.doc.customer &&
                r.message.customer !== frm.doc.customer
            ) {

                frappe.msgprint(
                    "This Sales Invoice does not belong to the selected Customer."
                );

                frm.set_value(
                    "reference_sale_invoice",
                    ""
                );

                return;
            }

            // Set invoice total
            let invoice_total =
                r.message.grand_total || 0;

            frm.set_value(
                "invoice_total",
                invoice_total
            );


            // Now find all previous submitted payments
            frappe.db.get_list(
                "Payment Entry",
                {
                    filters: {
                        reference_sale_invoice:
                            frm.doc.reference_sale_invoice,

                        payment_type: "Receive",

                        docstatus: 1
                    },

                    fields: [
                        "paid_amount"
                    ],

                    limit_page_length: 0
                }
            ).then(payments => {

                // Calculate previous payments
                let total_paid = 0;

                (payments || []).forEach(
                    function(payment) {

                        total_paid +=
                            payment.paid_amount || 0;

                    }
                );


                // Calculate remaining amount
                let remaining =
                    invoice_total - total_paid;


                if (remaining < 0) {
                    remaining = 0;
                }


                // Show remaining amount
                frm.set_value(
                    "remaining_amount",
                    remaining
                );

            });

        });

    },


    paid_amount(frm) {

        calculate_remaining_amount(frm);

    }

});


function calculate_remaining_amount(frm) {

    let invoice_total =
        frm.doc.invoice_total || 0;

    let previous_paid =
        frm.doc.paid_amount || 0;

    // The remaining_amount currently contains
    // the balance BEFORE this payment.
    let current_balance =
        frm.doc.remaining_amount || 0;


    // Prevent negative payment
    if (previous_paid < 0) {

        frappe.msgprint(
            "Paid Amount cannot be negative."
        );

        frm.set_value(
            "paid_amount",
            0
        );

        return;

    }


    // Don't allow payment greater than balance
    if (previous_paid > current_balance) {

        frappe.msgprint(
            `Paid Amount cannot exceed the remaining balance of ₹${current_balance}.`
        );

        frm.set_value(
            "paid_amount",
            current_balance
        );

        previous_paid = current_balance;

    }


    // Balance after this payment
    let remaining =
        current_balance - previous_paid;


    frm.set_value(
        "remaining_amount",
        remaining
    );

}

frappe.ui.form.on("Sales Order", {
    refresh(frm) {

        if (frm.doc.docstatus === 1) {

            frm.add_custom_button(
                "Generate Delivery Note",
                function() {

                    frappe.call({
                        method: "sap_assessment.api.o2c.generate_delivery_note",
                        args: {
                            sales_order_name: frm.doc.name
                        },

                        freeze: true,
                        freeze_message: "Generating Delivery Note...",

                        callback: function(r) {

                            if (r.message) {

                                frappe.msgprint(
                                    "Delivery Note " +
                                    r.message +
                                    " created successfully."
                                );

                                frappe.set_route(
                                    "Form",
                                    "Delivery Note",
                                    r.message
                                );
                            }
                        }
                    });

                }
            );
        }
    }
});

frappe.ui.form.on("Sales Order", {
    refresh(frm) {

        frm.add_custom_button("Create Contact", function () {

            let dialog = new frappe.ui.Dialog({
                title: "Create O2C Contact",

                fields: [
                    {
                        label: "First Name",
                        fieldname: "first_name",
                        fieldtype: "Data",
                        reqd: 1
                    }
                ],

                primary_action_label: "Create Contact",

                primary_action(values) {

                    console.log("First Name:", values.first_name);

                    dialog.hide();

                    frappe.route_options = {
                        first_name: values.first_name
                    };

                    frappe.new_doc("Contact");
                }
            });

            dialog.show();
        });
    }
});

frappe.ui.form.on("User", {
    refresh(frm) {
        frm.add_custom_button(
            "Send Welcome Email",
            function() {
                frappe.msgprint("Email Sent!");
            },
            "Actions"
        );
    }
});
